Definition algn (k x : Z) : Prop := x mod k = 0.

(* [comment removed for export] *)
Ltac notrap_algn A :=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso; generalize A; clear - K; unfold algn; intros;
    first [ rewrite land7_mod8 in K | rewrite land3_mod4 in K | rewrite land15_mod16 in K | idtac ];
    Z.div_mod_to_equations; lia
  | clear K ].

