(* [comment removed for export] *)
Lemma ImplBlock_xpres : forall LB SP X m m' b I,
  ImplBlock LB m b I -> xpres LB SP X m m' ->
  Forall (fun iv : Z * Z => b + SZ_SPCI_IMPL <= fst iv \/ snd iv <= b) X ->
  (0 < im_vcap I -> Forall (fun iv : Z * Z => im_vb I + 8 * im_vcap I <= fst iv \/ snd iv <= im_vb I) X) ->
  ImplBlock LB m' b I.
Proof.
  intros LB SP X m m' b I (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST) XP FX FV. exists p, j7.
  assert (XR : forall A n, b <= A -> A + n <= b + SZ_SPCI_IMPL -> xclient_range LB SP X A n).
  { intros A n H1 H2. split; [right; right; exists (p, b, SZ_SPCI_IMPL); split; [exact IN| cbn; lia]|].
    eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; lia. }
  unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN in *.
  split; [exact IN|]. split; [exact RB|]. split; [xp_keep XP XR|]. split; [exact OK|]. split; [exact EV|].
  split. { destruct PM as (PMC & LK & AL). split; [| split; [exact LK| exact AL]]. xp_keep XP XR. }
  split; [xp_keep XP XR|]. split; [exact LE|].
  destruct ST as [ST|(q & junk & INq & RBq & POS & CS)]; [left; exact ST| right]. exists q, junk.
  split; [exact INq|]. split; [exact RBq|]. split; [exact POS|].
  pose proof (rw_cells_bound _ _ _ _ CS) as B. destruct CS as [[WF BA] WR]. cbn in WF.
  eapply xpres_rw_cells; [exact XP| split; [split; [exact WF| exact BA] | exact WR] |].
  cbn [cells_size csize Nat.add] in *. split.
  - right; right. exists (q, im_vb I, 8 * im_vcap I). split; [exact INq| cbn; unfold zlength in *; lia].
  - eapply Forall_impl; [| exact (FV POS)]. intros [lo hi] K; cbn in *; unfold zlength in *; lia.
Qed.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

(* [comment removed for export] *)
Lemma FlatBuf_xpres : forall LB SP X m m' a F ds,
  FlatBuf LB m a F ds -> xpres LB SP X m m' -> xclient_range LB SP X a SZ_FB ->
  (F <> FB_empty -> Forall (fun iv : Z * Z => fb_end F <= fst iv \/ snd iv <= fb_begin F) X) ->
