Lemma StateBlock_xpres : forall LB SP X m m' b ioc implb S ds,
  StateBlock LB m b ioc implb S ds -> xpres LB SP X m m' ->
  Forall (fun iv : Z * Z => b + SZ_SPCI_STATE <= fst iv \/ snd iv <= b) X ->
  (st_fb S <> FB_empty -> Forall (fun iv : Z * Z => fb_end (st_fb S) <= fst iv \/ snd iv <= fb_begin (st_fb S)) X) ->
  StateBlock LB m' b ioc implb S ds.
Proof.
  intros LB SP X m m' b ioc implb S ds (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & PC & CO & E) XP FX FD.
  exists p, j7, j16, j4.
  assert (XR : forall A n, b <= A -> A + n <= b + SZ_SPCI_STATE -> xclient_range LB SP X A n).
  { intros A n H1 H2. split; [right; right; exists (p, b, SZ_SPCI_STATE); split; [exact IN| cbn; lia]|].
    eapply Forall_impl; [| exact FX]. intros [lo hi] K; cbn in *; lia. }
  unfold SZ_SPCI_STATE, O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP in *.
  split; [exact IN|]. split; [exact RB|]. split; [xp_keep XP XR|]. split; [exact OK|]. split; [exact EV|].
  split; [xp_keep XP XR|]. split; [xp_keep XP XR|].
  split. { destruct PM as (PMC & LK & AL). split; [| split; [exact LK| exact AL]]. xp_keep XP XR. }
  split. { eapply FlatBuf_xpres; [exact FB| exact XP| apply XR; unfold SZ_FB; lia| exact FD]. }
  split. { destruct PC as (PCC & LK & AL). split; [| split; [exact LK| exact AL]]. xp_keep XP XR. }
  split; [xp_keep XP XR| exact E].
Qed.

