Lemma AllocImpl_mono : forall LB LB' m a, (forall b, In b LB -> In b LB') -> AllocImpl LB m a -> AllocImpl LB' m a.
Proof. intros LB LB' m a SUB (p & j & IN & C). exists p, j. split; [apply SUB; exact IN| exact C]. Qed.
Lemma Registry_mono : forall LB LB' m r o f lk, (forall b, In b LB -> In b LB') -> Registry LB m r o f lk -> Registry LB' m r o f lk.
Proof. intros LB LB' m r o f lk SUB (p & j0 & j7 & IN & C). exists p, j0, j7. split; [apply SUB; exact IN| exact C]. Qed.
Lemma ConfigSvc_mono : forall LB LB' m c S, (forall b, In b LB -> In b LB') -> ConfigSvc LB m c S -> ConfigSvc LB' m c S.
Proof. intros LB LB' m c S SUB (p & j4 & j7 & IN & C). exists p, j4, j7. split; [apply SUB; exact IN| exact C]. Qed.
Lemma Scheduler_mono : forall LB LB' m s S, (forall b, In b LB -> In b LB') -> Scheduler LB m s S -> Scheduler LB' m s S.
Proof.
  intros LB LB' m s S SUB (p & j50 & jm & j109 & je & jt & j219 & j7 & IN & C). exists p, j50, jm, j109, je, jt, j219, j7.
  split; [apply SUB; exact IN| exact C].
Qed.
Lemma StreamSvc_mono : forall LB LB' m v S i, (forall b, In b LB -> In b LB') -> StreamSvc LB m v S i -> StreamSvc LB' m v S i.
Proof. intros LB LB' m v S i SUB (p & j7 & IN & C). exists p, j7. split; [apply SUB; exact IN| exact C]. Qed.
Lemma ImplBlock_mono : forall LB LB' m b I, (forall x, In x LB -> In x LB') -> ImplBlock LB m b I -> ImplBlock LB' m b I.
Proof.
  intros LB LB' m b I SUB (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST). exists p, j7.
  split; [apply SUB; exact IN|]. repeat (split; [assumption|]).
  destruct ST as [ST|(q & junk & INq & R)]; [left; exact ST| right]. exists q, junk. split; [apply SUB; exact INq| exact R].
Qed.
Lemma FlatBuf_mono : forall LB LB' m a F ds, (forall x, In x LB -> In x LB') -> FlatBuf LB m a F ds -> FlatBuf LB' m a F ds.
Proof.
  intros LB LB' m a F ds SUB (C & OK & L & D). split; [exact C|]. split; [| split; [exact L| exact D]].
  destruct OK as [E|(p & IN & R)]; [left; exact E| right]. exists p. split; [apply SUB; exact IN| exact R].
Qed.
Lemma StateBlock_mono : forall LB LB' m b ioc i S ds, (forall x, In x LB -> In x LB') -> StateBlock LB m b ioc i S ds -> StateBlock LB' m b ioc i S ds.
Proof.
  intros LB LB' m b ioc i S ds SUB (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & PC & CO & E).
  exists p, j7, j16, j4. split; [apply SUB; exact IN|]. repeat (split; [assumption|]).
  split; [eapply FlatBuf_mono; [exact SUB| exact FB]|]. repeat (split; [assumption|]). exact E.
Qed.

Lemma NoDup_app_disjoint : forall {A : Type} (l1 l2 : list A) (x : A),
  List.NoDup (l1 ++ l2) -> In x l1 -> In x l2 -> False.
Proof.
  induction l1 as [|a l1 IH]; intros l2 x ND H1 H2; [exact H1|].
  cbn in ND. inversion ND as [|y l NI ND']; subst.
  destruct H1 as [<-|H1]; [apply NI; apply in_or_app; right; exact H2| exact (IH _ _ ND' H1 H2)].
Qed.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Lemma blocks_neq_disjoint : forall s L m b b',
    hs_RHEAP H s L m -> In b L -> In b' L -> b <> b' ->
    blk_addr b + blk_size b <= blk_addr b' \/ blk_addr b' + blk_size b' <= blk_addr b.
  Proof.
    intros s L m b b' HP Hb Hb' NE. apply (hh_disj H HH _ _ _ _ _ HP Hb Hb').
    intros E. apply NE. eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact Hb| exact Hb'| exact E].
  Qed.

  (* [comment removed for export] *)
  Lemma fresh_outside_gen : forall s NEW LB m b SP a,
    hs_RHEAP H s (NEW ++ LB) m -> In b NEW -> hceil <= SP -> rclient_addr LB SP a ->
    a + 1 <= blk_addr b \/ blk_addr b + blk_size b <= a.
  Proof.
    intros s NEW LB m b SP a HP Hb CE HC.
    assert (INb : In b (NEW ++ LB)) by (apply in_or_app; left; exact Hb).
    pose proof (hh_blocks H HH _ _ _ _ HP INb) as (R1 & R2 & R3 & R4 & R5).
    destruct HC as [HC|[[HC _]|(b' & Hb' & Hr)]]; [right; lia| lia|].
    assert (INb' : In b' (NEW ++ LB)) by (apply in_or_app; right; exact Hb').
    pose proof (hh_nodup H HH _ _ _ HP) as ND. rewrite map_app in ND.
    destruct (hh_disj H HH _ _ _ _ _ HP INb INb') as [D|D]; [| lia| lia].
    intros E. eapply (NoDup_app_disjoint _ _ (blk_id b) ND); [apply in_map; exact Hb| rewrite E; apply in_map; exact Hb'].
  Qed.
End W.

