Definition mi_segA_post (sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (R EX ioc regb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk junk',
    ms' = MS (mkR (Z_to_bv 64 P_MI_RETU) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 regb) (Z_to_bv 64 (bv_unsigned sp + -72)) (Z_to_bv 64 P_CREATE_SSVC) (Z_to_bv 64 ioc) a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_DO_USE_SERVICE) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells usegs m' (bv_unsigned sp + -80) [CB 8 junk']
    /\ rw_cells usegs m' (bv_unsigned sp + -72) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 G_ID_SSVC)]
    /\ rw_cells usegs m' (bv_unsigned sp + -56) [C8 (Z_to_bv 64 P_MI_RET1)]
    /\ rw_cells usegs m' (bv_unsigned sp + -48) [CB 8 junk]
    /\ rw_cells usegs m' (bv_unsigned sp + -40) [C8 (Z_to_bv 64 0)]
    /\ rw_cells usegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra].
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma mi_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (R EX ioc regb allocb lo : Z) (j16 : list byte),
  ro_cells usegs m EX (AnyExecCells EX ioc j16) -> bv_unsigned sp <= EX -> 0 < EX -> EX + 56 <= 2^64 ->
  ro_cells usegs m ioc [C8 (wz allocb); C8 (wz regb)] -> bv_unsigned sp <= ioc -> ioc + 16 <= 2^64 -> ioc mod 8 = 0 ->
  ro_cells usegs m (regb + 48) [C8 (wz ioc)] -> 0 < regb -> regb + NEWSZ_REG <= lo ->
  XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + 96 <= bv_unsigned sp -> hceil <= lo ->
  EX mod 8 = 0 -> regb mod 16 = 0 -> bv_unsigned sp mod 16 = 0 ->                   (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (mi_segA_post sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc R EX ioc regb lo ra s0 s1 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 R) (Z_to_bv 64 EX) (Z_to_bv 64 0) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
