Definition mi_segB_post (gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (sp : word) (v lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' =>
    ms' = MS (mkR (Z_to_bv 64 P_MI_RET2) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 s0 s1
                  s0 s1 (Z_to_bv 64 (v + 48)) (Z_to_bv 64 (bv_unsigned sp + -40)) a4 a5 a6 a7
                  (Z_to_bv 64 (v + 48)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MAKE_SHARED_STATE) fc None m (seg_rom usegs)
    /\ munch [] m m /\ wmono usegs m m /\ mem_inv usegs m
    /\ stk usegs m lo (bv_unsigned sp + -48).

Lemma mi_segB : forall (rax sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 k0 k1 : word)
    (F : bvmap 5 word) fc (m : mem) (v lo : Z) (j8 : list byte),
  rw_cells usegs m (bv_unsigned sp + -80) [CB 8 j8; C8 k0; C8 k1; C8 (Z_to_bv 64 P_MI_RET1)] ->
  stk usegs m lo (bv_unsigned sp + -80) -> lo + 80 <= bv_unsigned sp ->
  0 < v -> v mod 16 = 0 -> v + 79 <= 2^64 ->
  mem_inv usegs m ->
  evt usegs (mi_segB_post gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc sp v lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MI_RETU) fc None m (seg_rom usegs)).
