(* [comment removed for export] *)
Definition mi_segC_post (sp gp tp t0 t1 t2 a6 a7 s0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (q x lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a2 a3 a4 a5 m',
    ms' = MS (mkR (Z_to_bv 64 P_MI_RET3) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 s0 (Z_to_bv 64 (q + 32))
                  (Z_to_bv 64 (q + 72)) (Z_to_bv 64 (bv_unsigned sp + -48)) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_UB_VEC_STATEP_EMPLACE_BACK) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp + -48); (bv_unsigned sp + -48, bv_unsigned sp + -40); (q + 32, q + 72)]%Z m m'
    /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -48)
    /\ PMutex m' (q + 32) EBUSY
    /\ rw_cells usegs m' (bv_unsigned sp + -48) [C8 (Z_to_bv 64 x)].

Lemma mi_segC : forall sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (R v q x lo : Z) (j8 : list byte),
  ro_cells usegs m (v + 48) [C8 (wz (q + 32))] -> 0 < v -> v + 79 <= hceil ->
  0 < q -> q + 96 <= hceil -> q mod 16 = 0 -> PMutex m (q + 32) 0 -> (v + 79 <= q \/ q + 96 <= v) ->
  ro_cells usegs m R [C8 (wz x)] -> bv_unsigned sp <= R -> R + 16 <= 2^64 -> 0 <= x < 2^64 ->
  rw_cells usegs m (bv_unsigned sp + -48) [CB 8 j8] ->
  stk usegs m lo (bv_unsigned sp + -48) -> lo + 48 + 16 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv usegs m ->
  evt usegs (mi_segC_post sp gp tp t0 t1 t2 a6 a7 (Z_to_bv 64 R) (Z_to_bv 64 (v + 48)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc q x lo m)
    (MS (mkR (Z_to_bv 64 P_MI_RET2) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 R) s1
             a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (v + 48)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MI_RET2) fc None m (seg_rom usegs)).
