=sPp#j$>sPq##"). Qed.


(* [comment removed for export] *)
(* [comment removed for export] *)

Definition MAKE_IMPL_STACK : Z := 80 + DUSC_STACK.   (* [comment removed for export] *)
(* [comment removed for export] *)

(* [comment removed for export] *)
Definition sched_elt (ioc schedb cfgb : Z) : svce := mkSE schedb (sched_hdr ioc cfgb) TI_NAME_SCHED.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

Definition make_impl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (R ioc allocb regb cfgb schedb slk sst ssh lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState)
                    (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL /\ rblock_range stb SZ_SPCI_STATE /\ rblock_range va 8
      /\ hs_RHEAP H s' (mi_LB p1 v p2 q p3 stb p4 va LB) m'
      /\ rw_cells usegs m' R [C8 (wz (stb + O_SPC_STORAGE)); C8 (wz stb)]
      /\ rw_cells usegs m' ioc (IoCtxCells allocb regb schedb)
      /\ AllocImpl (mi_LB p1 v p2 q p3 stb p4 va LB) m' allocb
      /\ Registry (mi_LB p1 v p2 q p3 stb p4 va LB) m' regb ioc v 0
      /\ ConfigSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m' cfgb (cfg_hdr ioc)
      /\ Scheduler (mi_LB p1 v p2 q p3 stb p4 va LB) m' schedb (mkSCH (sched_hdr ioc cfgb) slk sst ssh)
      /\ StreamSvc (mi_LB p1 v p2 q p3 stb p4 va LB) m' v (ssvc_hdr ioc schedb) q
      /\ ImplBlock (mi_LB p1 v p2 q p3 stb p4 va LB) m' q (impl_after va stb)
      /\ StateBlock (mi_LB p1 v p2 q p3 stb p4 va LB) m' stb ioc q state_init []
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(R, R + 16); (regb, regb + NEWSZ_REG)] m m'.

  Definition make_impl_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (R EX ioc allocb regb cfgb schedb slk sst ssh lo B : Z) (errv : word) (jr j16 : list byte),
      a0 = Z_to_bv 64 R -> a1 = Z_to_bv 64 EX -> a2 = Z_to_bv 64 0 ->
      (* [comment removed for export] *)
      rw_cells usegs m R [CB 16 jr] -> bv_unsigned sp <= R -> R + 16 <= B -> R mod 8 = 0 ->
      ro_cells usegs m EX (AnyExecCells EX ioc j16) -> bv_unsigned sp <= EX -> EX + 56 <= 2^64 -> EX mod 8 = 0 ->
      (R + 16 <= EX \/ EX + 56 <= R) ->
      (* [comment removed for export] *)
      rw_cells usegs m ioc (IoCtxCells allocb regb schedb) -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 -> ioc mod 8 = 0 ->
      (R + 16 <= ioc \/ ioc + 24 <= R) ->
      AllocImpl LB m allocb -> Registry LB m regb ioc schedb 0 -> ConfigSvc LB m cfgb (cfg_hdr ioc) ->
      Scheduler LB m schedb (mkSCH (sched_hdr ioc cfgb) slk sst ssh) -> XStatics m ->
      (* [comment removed for export] *)
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + MAKE_IMPL_LIVE <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 4 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B < 2^64 ->
      (* [comment removed for export] *)
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - MAKE_IMPL_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned sp mod 16 = 0 ->                                                      (* [comment removed for export] *)
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (make_impl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB R ioc allocb regb cfgb schedb slk sst ssh lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_SSVC_MAKE_IMPL) fc None m (seg_rom usegs)) mo).

  Lemma make_impl_spec : make_impl_stmt.
  Proof.
    unfold make_impl_stmt. intros until j16.
    intros -> -> -> RR SPR RB R8 REX SPE EXH EX8 DRE IOC SPI IOH IO8 DRI AI REG CFG SCH XS HP KREL BUD BUDC AUX SPB BHI ST CEIL LO ERR MI TP SP16 RA.
    pose proof LO as LO'.
    change (sep R 16 EX 56) in DRE. change (sep R 16 ioc 24) in DRI.
    unfold MAKE_IMPL_STACK, DUSC_STACK, CREATE_SSVC_STACK, MAKE_SHARED_IMPL_STACK, SHCOUNT_CTOR_STACK, ROPNEW_STACK, RMALLOC_STACK in LO.
    unfold MAKE_IMPL_LIVE in BUD.
    pose proof CEIL as CEIL'. hcb. sp_range sp.
    assert (EA : errno_addr (Z_to_bv 64 RATP) = RERRNO) by (unfold RATP, RERRNO; rewrite unsigned_lit; lia).
    subst tp. rewrite EA in ERR.
    assert (HB : forall b, In b LB -> blk_addr b + blk_size b <= hceil).
    { intros b Hb. destruct (hh_blocks H HH _ _ _ b HP Hb) as (_ & _ & _ & H4 & _). exact H4. }
    (* [comment removed for export] *)
    pose proof REG as (pr & j0 & jr7 & INR & _). pose proof (Registry_owner_ro _ _ _ _ _ _ REG) as ROWN. unfold O_REG_OWNER in ROWN.
    pose proof CFG as (pc & j4 & jc7 & INC & _).
    pose proof SCH as (ps & j50 & jm & j109 & je & jt & j219 & js7 & INS & SHC & _).
    pose proof AI as (pa & ja & INA & _).
    pose proof (hh_blocks H HH _ _ _ _ HP INR) as (G1 & G2 & G3 & G4 & G5). cbn in G1, G2, G3, G4, G5.
    pose proof (hh_blocks H HH _ _ _ _ HP INC) as (Y1 & Y2 & Y3 & Y4 & Y5). cbn in Y1, Y2, Y3, Y4, Y5.
    pose proof (hh_blocks H HH _ _ _ _ HP INS) as (S1 & S2 & S3 & S4 & S5). cbn in S1, S2, S3, S4, S5.
    change (algn 16 regb) in G2. change (algn 16 cfgb) in Y2. change (algn 16 schedb) in S2. change (algn 16 (bv_unsigned sp)) in SP16.
    pose proof (hh_blocks H HH _ _ _ _ HP INA) as (A1 & _ & A3 & A4 & A5). cbn in A1, A3, A4, A5.
    unfold NEWSZ_REG, NEWSZ_CFG, NEWSZ_SCH, NEWSZ_SSVC, SZ_ALLOCIMPL, SZ_SPCI_IMPL, SZ_SPCI_STATE, O_SPC_STORAGE in *.
    assert (DSR : sep schedb 287 regb 79).
    { destruct (blocks_neq_disjoint H HH _ _ _ _ _ HP INS INR ltac:(intros E; injection E; lia)) as [D|D]; cbn in D; unfold sep; lia. }
    assert (DCR : sep cfgb 71 regb 79).
    { destruct (blocks_neq_disjoint H HH _ _ _ _ _ HP INC INR ltac:(intros E; injection E; lia)) as [D|D]; cbn in D; unfold sep; lia. }
    (* [comment removed for export] *)
    assert (RIOC : ro_cells usegs m ioc [C8 (wz allocb); C8 (wz regb)]).
    { unfold IoCtxCells in IOC. apply (proj1 (rw_cells_app _ _ _ [_; _] [_])) in IOC. exact (proj1 (proj1 IOC)). }
    pose proof (ro_cells_bound _ _ _ _ REX) as BE. cbn [cells_size csize Nat.add length AnyExecCells] in BE.
    (* [comment removed for export] *)
    eapply (hh_evt_then H HH); [exact KREL| |].
    { eapply mi_segA with (lo := lo) (regb := regb) (ioc := ioc) (allocb := allocb) (EX := EX); try eassumption; try lia.
      all: first [unfold NEWSZ_REG; lia | Z.div_mod_to_equations; lia]. }
    intros ms1 PO. unfold mi_segA_post in PO. clear R8 EX8.
    destruct PO as (m1 & junk8 & junku & -> & MU & WM & MI1 & ST1 & FU0 & KEY & FRA & FR0 & FCP & FRS).
    (* [comment removed for export] *)
    eapply (rw_cells_transport usegs _ m m1) in ERR; [| exact MU| exact WM| unfold RERRNO in *; cbn; lia].
    eapply (rw_cells_transport usegs _ m m1) in RR; [| exact MU| exact WM| cbn; lia].
    eapply (ro_cells_transport usegs _ m m1) in REX; [| exact MU| cbn; lia].
